class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(t):
            if t == 0:
                return 0
            if t < x:
                return min(2 * t - 1, 2 * (x - t))
            p, c = x, 1
            while p * x <= t:
                p *= x
                c += 1
            q, r = divmod(t, p)
            return min(q * c + dp(r), (q + 1) * c + dp(p - r))

        return dp(target)

