class Solution {
public:
    int x;
    unordered_map<long long,int> memo;

    int dp(long long t) {
        if (t == 0) return 0;
        if (t < x) return min(2LL * t - 1, 2LL * (x - t));
        auto it = memo.find(t);
        if (it != memo.end()) return it->second;
        long long p = x;
        int c = 1;
        while (p * x <= t) { p *= x; c++; }
        long long q = t / p, r = t % p;
        int res = min(q * c + dp(r), (q + 1) * c + dp(p - r));
        memo[t] = res;
        return res;
    }

    int leastOpsExpressTarget(int x, int target) {
        this->x = x;
        return dp(target);
    }
};

