class Solution {
    private int x;
    private Map<Long, Integer> memo = new HashMap<>();

    private int dp(long t) {
        if (t == 0) return 0;
        if (t < x) return (int) Math.min(2L * t - 1, 2L * (x - t));
        Integer cached = memo.get(t);
        if (cached != null) return cached;
        long p = x;
        int c = 1;
        while (p * x <= t) { p *= x; c++; }
        long q = t / p, r = t % p;
        int res = Math.min((int)(q * c) + dp(r), (int)((q + 1) * c) + dp(p - r));
        memo.put(t, res);
        return res;
    }

    public int leastOpsExpressTarget(int x, int target) {
        this.x = x;
        memo.clear();
        return dp(target);
    }
}

