var leastOpsExpressTarget = function(x, target) {
    const memo = new Map();
    function dp(t) {
        if (t === 0) return 0;
        if (t < x) return Math.min(2 * t - 1, 2 * (x - t));
        if (memo.has(t)) return memo.get(t);
        let p = x, c = 1;
        while (p * x <= t) { p *= x; c++; }
        const q = Math.floor(t / p), r = t % p;
        const res = Math.min(q * c + dp(r), (q + 1) * c + dp(p - r));
        memo.set(t, res);
        return res;
    }
    return dp(target);
};

