    int leastOpsExpressTarget(int x, int target) {
        long long pos = 0, neg = 0;
        int k = 0, K = 0;
        while (target > 0) {
            int d = target % x;
            target /= x;
            if (k == 0) {
                pos = 2LL * d;
                neg = 2LL * (x - d);
            } else {
                long long np = min(d * (long long)k + pos, (d + 1) * (long long)k + neg);
                long long nn = min((x - d) * (long long)k + pos, (x - d - 1) * (long long)k + neg);
                pos = np; neg = nn;
            }
            k++; K = k;
        }
        return (int)min(pos + K, neg + K - 1);
    }
};

